        &lt;tr&gt;&lt;td&gt;Indexer ratio-1 · G8&lt;/td&gt;&lt;td&gt;I20&lt;/td&gt;&lt;td&gt;105,984 B&lt;/td&gt;&lt;td&gt;8,704 B&lt;/td&gt;&lt;td&gt;114,688 B&lt;/td&gt;&lt;/tr&gt;
        &lt;tr&gt;&lt;td&gt;Compressor ring · G9&lt;/td&gt;&lt;td&gt;L2, L8, L14&lt;/td&gt;&lt;td&gt;0&lt;/td&gt;&lt;td&gt;32,768 B&lt;/td&gt;&lt;td&gt;114,688 B&lt;/td&gt;&lt;/tr&gt;
